cases.bad:
// manifest.json: content-script run_at: document_idle (default)
// MAIN world posts __YT_DETECTED_SUBTITLES at ~3-4s
// ISOLATED listener registers at document_idle (~3-4s) — race → message lost, no buffering

cases.good:
// manifest.json: content-script run_at: document_start
// Listener (no DOM dependency) registers immediately at document_start — before MAIN world posts
window.addEventListener('message', (e) => { if (e.data?.type === '__YT_DETECTED_SUBTITLES') relay(e.data); });
// DOM-dependent page scan defers to DOMContentLoaded
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => runPageScan());
} else { runPageScan(); }
